; =====================================================================
;  DISPLAY.ASM -- display list, DLI, VBI and map drawing
;
;  Screen layout (192 scan lines, D12):
;    24 blank lines
;     2 x ANTIC mode 2  status bar  (ROM font, OS shadow colours)
;    11 x ANTIC mode 5  map         (map font, colours set by DLI)
;
;  One map square = one tile = 2 mode 5 characters = 8 x 8 pixels,
;  8 colour clocks wide and 16 scan lines tall; 20 x 11 squares.
;  Tiles, font and island data come from TILES.ASM / FONT_MAP.ASM /
;  ISLANDS.ASM, generated by tools/mkfont.py.
;
;  The DLI on the last status line switches CHBASE and the colour
;  registers for the map zone.  The OS VBI restores the status-bar
;  values from the shadow registers at the top of every frame.
; =====================================================================

MAPROWS =  11           ; mode 5 lines (square rows) in the map zone
MAPSQ   =  20           ; squares per row
MAPCOLS =  40           ; characters per line, normal playfield width
HP_MAP  =  48           ; horizontal position of map column 0 (P/M)
PM_MAP  =  24           ; double-line P/M line of map row 0 (scan line 48)

; Status bar colours (OS shadows)
C_SBAR  =  $82          ; status bar background (COLPF2)
C_STXT  =  $0E          ; status bar text luminance (COLPF1)
C_SBRD  =  $00          ; status bar border (COLBK)

; Map palette (D16), set by the DLI
C_SEA   =  $84          ; COLBK  -- sea
C_GRASS =  $C6          ; COLPF0 -- grass
C_DARK  =  $00          ; COLPF1 -- black: fort, factory, crop, rebel, boats
C_LIGHT =  $1C          ; COLPF2 -- yellow: beach, house roof, smoke, sail
C_WHITE =  $0E          ; COLPF3 -- white (inverse chars): school, hospital

; ---------------------------------------------------------------------
;  DISP_INIT -- install display list, DLI and VBI.
;  Writes only RAM vectors and shadows; calls no OS routines.
; ---------------------------------------------------------------------
DISP_INIT
        LDA #0
        STA NMIEN       ; no VBI/DLI while vectors are patched
        STA SDMCTL
        STA DMACTL

        LDX #STATLEN-1  ; status lines from template
DI_STAT LDA STATTPL,X
        STA STATUS1,X
        DEX
        BPL DI_STAT

        JSR MAP_ROWS
        JSR MAP_DRAW

        LDA #<DLI_MAP
        STA VDSLST
        LDA #>DLI_MAP
        STA VDSLST+1

        LDA VVBLKD      ; chain to whatever deferred VBI was there
        STA OLDVBD
        LDA VVBLKD+1
        STA OLDVBD+1
        LDA #<VBI_D
        STA VVBLKD
        LDA #>VBI_D
        STA VVBLKD+1

        LDA #<DLIST
        STA SDLSTL
        LDA #>DLIST
        STA SDLSTH

        LDA #C_SBAR
        STA COLOR2
        LDA #C_STXT
        STA COLOR1
        LDA #C_SBRD
        STA COLOR4
        LDA #ROMFONT
        STA CHBAS

        LDA #DMA_NORM
        STA SDMCTL
        LDA #NMI_VBI+NMI_DLI
        STA NMIEN
        RTS

; ---------------------------------------------------------------------
;  DLI_MAP -- switch font and colours for the map zone
; ---------------------------------------------------------------------
DLI_MAP
        PHA
        TXA
        PHA
        TYA
        PHA
        LDA #C_SEA
        LDX #C_GRASS
        LDY #C_DARK
        STA WSYNC
        STA COLBK
        STX COLPF0
        STY COLPF1
        LDA #C_LIGHT
        STA COLPF2
        LDA #C_WHITE
        STA COLPF3
        LDA #>MAPFONT
        STA CHBASE
        PLA
        TAY
        PLA
        TAX
        PLA
        RTI

; ---------------------------------------------------------------------
;  VBI_D -- deferred VBI: frame counter, keep attract mode off
; ---------------------------------------------------------------------
VBI_D
        INC FRAME
        LDA #0
        STA ATRACT
        JMP (OLDVBD)

; ---------------------------------------------------------------------
;  MAP_ROWS -- build the screen address of each map row
;  Trashes A, X.
; ---------------------------------------------------------------------
MAP_ROWS
        LDA #<MAPSCR
        STA ROWLO
        LDA #>MAPSCR
        STA ROWHI
        LDX #0
MR_NEXT CLC
        LDA ROWLO,X
        ADC #MAPCOLS
        STA ROWLO+1,X
        LDA ROWHI,X
        ADC #0
        STA ROWHI+1,X
        INX
        CPX #MAPROWS-1
        BNE MR_NEXT
        RTS

; ---------------------------------------------------------------------
;  MAP_DRAW -- draw the island terrain (ISLTILE) into screen memory
;  Each tile becomes characters TILECH[t] and TILECH[t]+1.
;  Trashes A, X, Y, ZPTR.
; ---------------------------------------------------------------------
MAP_DRAW
        LDX #0
        STX MROW
        STX GIDX
MD_ROW  LDY MROW
        LDA ROWLO,Y
        STA ZPTR
        LDA ROWHI,Y
        STA ZPTR+1
        LDY #0          ; character column
MD_COL  LDX GIDX
        LDA ISLTILE,X   ; tile number
        TAX
        LDA TILECH,X    ; left character
        STA (ZPTR),Y
        INY
        CLC
        ADC #1          ; right character (bit 7 kept: codes are even)
        STA (ZPTR),Y
        INY
        INC GIDX
        CPY #MAPCOLS
        BNE MD_COL
        INC MROW
        LDA MROW
        CMP #MAPROWS
        BNE MD_ROW
        RTS

; ---------------------------------------------------------------------
;  Status bar template (screen codes), 2 lines of 40.  Copied into the
;  RAM status lines STATUS1/STATUS2 (VARS.ASM) by DISP_INIT.
; ---------------------------------------------------------------------
STATTPL .SBYTE " ACADIA - UTOPIA FOR THE ATARI 800XL    "
        .SBYTE "J0:0 F0:0 J1:0 F1:0 KEY:- FRM:00        "
STATLEN =  80

; Offsets of the live fields in STATUS2
ST_J0   =  3
ST_F0   =  8
ST_J1   =  13
ST_F1   =  18
ST_KEY  =  24
ST_FRM  =  30

; ---------------------------------------------------------------------
;  MAP_IDX -- grid index of a square
;  In: X = column (0-19), Y = row (0-10).  Out: A = row*20+column.
;  X and Y kept.
; ---------------------------------------------------------------------
MAP_IDX
        TXA
        CLC
        ADC ROWIDX,Y
        RTS

ROWIDX  .BYTE 0,20,40,60,80,100,120,140,160,180,200

; ---------------------------------------------------------------------
;  MAP_PUT -- draw one tile on the map
;  In: A = tile, X = column (0-19), Y = row (0-10).
;  X kept; trashes A, Y, ZPTR, MTILE.
; ---------------------------------------------------------------------
MAP_PUT
        STA MTILE
        LDA ROWLO,Y
        STA ZPTR
        LDA ROWHI,Y
        STA ZPTR+1
        TXA
        PHA
        ASL A           ; two characters per square
        TAY
        LDX MTILE
        LDA TILECH,X    ; left character
        STA (ZPTR),Y
        INY
        CLC
        ADC #1          ; right character
        STA (ZPTR),Y
        PLA
        TAX
        RTS

; ---------------------------------------------------------------------
;  HPOS_COL -- map column under a normal-width P/M horizontal position
;  In: A = horizontal position.  Out: A = column, C clear; C set if
;  the position is off the map.
; ---------------------------------------------------------------------
HPOS_COL
        SEC
        SBC #HP_MAP
        BCC HC_OFF
        LSR A           ; 8 colour clocks per square
        LSR A
        LSR A
        CMP #MAPSQ      ; C set if column >= 20
        RTS
HC_OFF  SEC
        RTS

; ---------------------------------------------------------------------
;  PMY_ROW -- map row under a double-line P/M vertical line
;  In: A = P/M line.  Out: A = row, C clear; C set if off the map.
; ---------------------------------------------------------------------
PMY_ROW
        SEC
        SBC #PM_MAP
        BCC PR_OFF
        LSR A           ; 8 P/M lines (16 scan lines) per square
        LSR A
        LSR A
        CMP #MAPROWS    ; C set if row >= 11
        RTS
PR_OFF  SEC
        RTS

; Tile-to-character table and island data (generated)
        .INCLUDE "islands.asm"

; Display variables (FRAME, ROWLO/ROWHI, MROW, GIDX, MTILE, STATUS1/2)
; live in VARS.ASM.

; =====================================================================
;  Fixed-address data.  Each block must stay on its own boundary:
;  font 1K aligned, display list inside one 1K page, screen inside 4K.
; =====================================================================

; Map font at $3000 (generated)
        .INCLUDE "font_map.asm"

; ---------------------------------------------------------------------
;  Map screen memory (MAPROWS x MAPCOLS, RAM, drawn at run time)
; ---------------------------------------------------------------------
MAPSCR  =  $3400

; ---------------------------------------------------------------------
;  Display list
; ---------------------------------------------------------------------
        *= $3800
DLIST
        .BYTE DL_BLANK8,DL_BLANK8,DL_BLANK8
        .BYTE DL_LMS+DL_MODE2
        .WORD STATUS1
        .BYTE DL_DLI+DL_MODE2           ; DLI fires at end of this line
        .BYTE DL_LMS+DL_MODE5
        .WORD MAPSCR
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5,DL_MODE5
        .BYTE DL_JVB
        .WORD DLIST
